import { BlockedNotice, Surface, inputClass } from "@/components/app-ui";
export default function NewVendorProductPage() { return <div className="space-y-5"><div><p className="text-xs font-semibold uppercase tracking-[.16em] text-muted-foreground">Seller workspace</p><h1 className="mt-2 text-3xl font-semibold tracking-tight">Add a product</h1><p className="mt-2 text-sm text-muted-foreground">Prepare the details for a new marketplace listing.</p></div><BlockedNotice title="Product creation is disabled" detail="The backend create route currently has no image upload middleware. This form cannot submit until the API contract is repaired." /><Surface><fieldset disabled className="grid gap-4 sm:grid-cols-2"><label className="space-y-1.5 text-sm font-medium">Product name<input className={inputClass} /></label><label className="space-y-1.5 text-sm font-medium">SKU<input className={inputClass} /></label><label className="space-y-1.5 text-sm font-medium">Price<input type="number" className={inputClass} /></label><label className="space-y-1.5 text-sm font-medium">Discount %<input type="number" className={inputClass} /></label><label className="space-y-1.5 text-sm font-medium">Stock quantity<input type="number" className={inputClass} /></label><label className="space-y-1.5 text-sm font-medium">Category ID<input className={inputClass} /></label><label className="space-y-1.5 text-sm font-medium sm:col-span-2">Description<textarea rows={4} className={`${inputClass} h-auto py-3`} /></label><label className="space-y-1.5 text-sm font-medium sm:col-span-2">Product images<input type="file" accept="image/*" multiple className={inputClass} /></label></fieldset><button disabled className="mt-5 min-h-11 rounded-md bg-primary px-5 text-sm font-medium text-primary-foreground opacity-50">Save product unavailable</button></Surface></div>; }
